/** Managed storage witness (operator rule 2026-10-28): per-node storage is generated by the
 * framework, never a user requirement. Real Chromium + real authoring API, beginner view.
 * On the reusable project: gallery Blank -> empty canvas -> add Propose (palette), Implement
 * and Validate (`+`) -> no storage socket, inspector row, problem or "Create external
 * input" is ever shown -> the draft is complete -> Save. The saved source must bind each
 * node's storage exactly like examples/workflow_declarations/reusable_candidate.py: one
 * ManagedCandidateBinding(id="<node>_store", contract="storage") per node, read by that
 * node's `storage` argument, and a managed proposal request.
 * Fails if storage is asked of the user, if a literal storage binding is saved, or if the
 * binding shape or id convention differs from the shipped example.
 * Explicit env: EDITOR_PYTHON, CONSOLE_PLAYWRIGHT_MODULE, CONSOLE_BROWSER_EXECUTABLE. */
import assert from 'node:assert/strict';
import {execFileSync, spawn} from 'node:child_process';
import {createRequire} from 'node:module';
import {dirname, resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
import {createInterface} from 'node:readline';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
for (const name of ['EDITOR_PYTHON', 'CONSOLE_PLAYWRIGHT_MODULE', 'CONSOLE_BROWSER_EXECUTABLE']) assert.ok(process.env[name], `Set ${name}`);
const server = spawn(process.env.EDITOR_PYTHON, ['-m', 'tests.browser.workflow_editor_server'], {cwd: root, stdio: ['ignore', 'pipe', 'pipe']});
let errors = '', browser;
server.stderr.on('data', chunk => { errors += chunk; });
const lines = createInterface({input: server.stdout});
const waitUntil = async (predicate, what = 'condition') => {
  const deadline = Date.now() + 20000;
  while (!(await predicate())) { if (Date.now() > deadline) throw new Error(`${what} timed out`); await new Promise(r => setTimeout(r, 50)); }
};
// (capability, argument) -> binding kind/contract/id for every storage argument, from Python.
const storageShape = path => JSON.parse(execFileSync(process.env.EDITOR_PYTHON, ['-c', `
import json, sys
from pathlib import Path
from workflows.definition import parse_workflow_source
d = parse_workflow_source(Path(sys.argv[1]).read_text())
ext = {e.id: e for e in d.definition.externals}
rows = []
for n in d.definition.nodes:
    req = n.request
    if req.kind == 'external':
        e = ext[req.binding]; rows.append({'node': n.id, 'capability': n.capability, 'argument': None, 'kind': e.kind, 'contract': e.contract, 'id': e.id})
        continue
    for a in req.arguments:
        if a.name == 'storage':
            e = ext[a.source.binding]; rows.append({'node': n.id, 'capability': n.capability, 'argument': 'storage', 'kind': e.kind, 'contract': e.contract, 'id': e.id})
print(json.dumps({'rows': rows, 'literal_storage': [e.id for e in d.definition.externals if e.kind != 'managed_candidate' and e.contract == 'storage']}))
`, path], {cwd: root, encoding: 'utf8', env: {...process.env, PYTHONPATH: resolve(root, 'src')}}));
try {
  const metadata = await new Promise((accept, reject) => {
    const timer = setTimeout(() => reject(new Error(`startup timeout ${errors}`)), 30000);
    lines.on('line', line => { try { const v = JSON.parse(line); if (v.origin && v.token) { clearTimeout(timer); lines.close(); accept(v); } } catch { /* info line */ } });
    server.once('exit', code => { clearTimeout(timer); reject(new Error(`server ${code} ${errors}`)); });
  });
  const {chromium} = createRequire(import.meta.url)(process.env.CONSOLE_PLAYWRIGHT_MODULE);
  browser = await chromium.launch({headless: true, executablePath: process.env.CONSOLE_BROWSER_EXECUTABLE});
  const page = await browser.newPage({viewport: {width: 1440, height: 1100}}), faults = [];
  page.on('pageerror', error => faults.push(error.message));
  const status = () => page.locator('#editor-status').textContent(), pending = () => page.locator('#editor-pending').textContent();
  const cards = () => page.locator('#editor-graph .circuit-card').evaluateAll(items => items.map(item => ({id: item.dataset.node, capability: item.dataset.capability})));
  await page.goto(metadata.origin + '/#workflow');
  await page.locator('#token').fill(metadata.token); await page.locator('#access-form button').click();
  await waitUntil(async () => (await status()).includes('Opened supported'), 'open');
  await page.locator('#editor-project').selectOption('reusable');
  await waitUntil(async () => (await page.locator('#editor-path').textContent()) === metadata.reusable_source, 'reusable project');
  const example = storageShape(resolve(root, 'examples/workflow_declarations/reusable_candidate.py'));

  // Blank: an empty canvas in the draft.
  await page.locator('#editor-template-open').click();
  await page.locator('.template-card[data-template="blank"]').click();
  await page.locator('#editor-template-blank').click();
  await waitUntil(async () => (await cards()).length === 0, 'blank canvas');
  assert.equal(await page.locator('#workflow-start-guide').isVisible(), true, 'The empty state shows on a blank canvas');

  // Propose from the palette (external route), then Implement and Validate with `+`.
  const palette = page.locator('#editor-palette');
  await waitUntil(async () => (await palette.locator('.palette-entry').count()) > 0, 'catalog');
  await palette.locator('.palette-search').fill('propos');
  await palette.locator('.palette-entry[data-capability="proposal"][data-protocol=""]').click();
  await waitUntil(async () => (await cards()).length === 1, 'proposal added');
  const plus = async (from, protocol) => {
    const card = page.locator(`.circuit-card[data-node="${from}"]`);
    await card.hover(); await card.locator(':scope > .circuit-add-next').click();
    await page.locator(`.canvas-add-option[data-protocol="${protocol}"]`).click();
  };
  const proposal = (await cards())[0].id;
  await plus(proposal, 'proposal-to-implementation');
  await waitUntil(async () => (await cards()).length === 2, 'implementation added');
  const implementation = (await cards()).find(item => item.capability === 'implementation').id;
  await plus(implementation, 'implementation-to-validation');
  await waitUntil(async () => (await cards()).length === 3, 'validation added');
  const validation = (await cards()).find(item => item.capability === 'validation').id;

  // Storage is never asked of the user.
  await waitUntil(async () => (await pending()).includes('· complete'), 'draft complete without any storage input');
  for (const id of [implementation, validation]) {
    assert.equal(await page.locator(`#circuit-input-${id}-storage`).count(), 0, `${id}: no storage socket`);
    await page.locator(`#circuit-node-${id}`).click();
    assert.equal(await page.locator('#editor-inspector select[data-argument="storage"]').count(), 0, `${id}: no storage row`);
    assert.equal(await page.locator('#editor-inspector .external-input-create').count(), 0, `${id}: no "Create external input"`);
  }
  assert.equal(await page.locator(`#circuit-input-${proposal}-request`).count(), 0, 'The managed proposal request has no socket');
  assert.equal(await page.locator('#problems-chip').isVisible(), false, 'No problem asks for storage');

  // Save; the file binds storage exactly like the shipped example.
  await page.locator('#editor-review').click();
  await waitUntil(async () => !(await page.locator('#editor-save').isDisabled()), 'checked');
  await page.locator('#editor-save').click();
  await waitUntil(async () => (await status()).includes('Saved reviewed bytes'), 'saved');
  const saved = storageShape(metadata.reusable_source);
  assert.deepEqual(saved.literal_storage, [], 'No literal storage binding');
  const shape = rows => rows.map(({capability, argument, kind, contract}) => ({capability, argument, kind, contract}))
    .sort((a, b) => `${a.capability}${a.argument}`.localeCompare(`${b.capability}${b.argument}`));
  assert.deepEqual(shape(saved.rows), shape(example.rows), 'Same binding shape as reusable_candidate.py');
  for (const row of saved.rows.filter(item => item.argument === 'storage')) assert.equal(row.id, `${row.node}_store`, 'Example id convention <node>_store');
  assert.equal(new Set(saved.rows.map(item => item.id)).size, saved.rows.length, 'One managed binding per node');
  assert.deepEqual(faults, []);
  console.log('PASS managed storage: Blank -> Propose/Implement/Validate without any storage input; saved bindings match reusable_candidate.py');
} finally {
  await browser?.close();
  server.kill();
}
